        uint256 amtDark,
        uint256 amtDarkMin,
        uint256 amtFtmMin
    )
        external
        payable
        returns (
            uint256,
            uint256,
            uint256
        )
    {
        require(amtDark != 0 && msg.value != 0, "amounts can't be 0");
