function processAsyncDefiInteraction(uint256 interactionNonce) external returns (bool completed) {
        // call canFinalise on the bridge
        // call finalise on the bridge
        DefiInteraction storage interaction = defiInteractions[
            interactionNonce
        ];
        require(
            interaction.bridgeAddress != address(0),
            "Rollup Contract: UNKNOWN_NONCE"
        );

        (uint256 outputValueA, uint256 outputValueB, bool interactionComplete) = IDefiBridge(
            interaction.bridgeAddress
        ).finalise(
                interaction.inputAssetA,
                interaction.inputAssetB,
                interaction.outputAssetA,
                interaction.outputAssetB,
                interaction.interactionNonce,
                uint64(interaction.auxInputData)
            );
        completed = interactionComplete;

        if (
            outputValueB > 0 &&
            interaction.outputAssetB.assetType ==
            AztecTypes.AztecAssetType.NOT_USED
        ) {
            require(false, "Non-zero output value on non-existant asset!");
        }
        if (outputValueA == 0 && outputValueB == 0) {
            // issue refund.
            transferTokensAsync(
                address(interaction.bridgeAddress),
                interaction.inputAssetA,
                interaction.totalInputValue,
                interaction.interactionNonce
            );
        } else {
            // transfer output tokens to rollup contract
            transferTokensAsync(
                address(interaction.bridgeAddress),
                interaction.outputAssetA,
                outputValueA,
                interaction.interactionNonce
            );
            transferTokensAsync(
                address(interaction.bridgeAddress),
                interaction.outputAssetB,
                outputValueB,
                interaction.interactionNonce
            );
        }

        emit DefiBridgeProcessed(
            0,
            interaction.interactionNonce,
            interaction.totalInputValue,
            outputValueA,
            outputValueB,
            true
        );
    }

function _convert(ConvertArgs memory convertArgs) private returns (
            ConvertReturnValues memory results
        ) {
        defiInteractions[convertArgs.interactionNonce] = DefiInteraction(
            convertArgs.bridgeAddress,
            convertArgs.inputAssetA,
            convertArgs.inputAssetB,
            convertArgs.outputAssetA,
            convertArgs.outputAssetB,
            convertArgs.totalInputValue,
            convertArgs.interactionNonce,
            convertArgs.auxInputData
        );
        uint256 gas = bridgeGasLimits[convertArgs.bridgeAddress]  > 0 ? bridgeGasLimits[convertArgs.bridgeAddress]: uint256(150000000);

        (bool success, bytes memory result) = address(bridgeProxy).delegatecall{gas: gas}(
            abi.encodeWithSelector(
                DEFI_BRIDGE_PROXY_CONVERT_SELECTOR,
                convertArgs.bridgeAddress,
                convertArgs.inputAssetA,
                convertArgs.inputAssetB,
                convertArgs.outputAssetA,
                convertArgs.outputAssetB,
                convertArgs.totalInputValue,
                convertArgs.interactionNonce,
                convertArgs.auxInputData,
                convertArgs.ethPaymentsSlot
            )
        );
        results = ConvertReturnValues(0, 0, false);

        if (success) {
            (uint256 outputValueA, uint256 outputValueB, bool isAsync) = abi.decode(
                result,
                (uint256, uint256, bool)
            );
            if (!isAsync) {
                emit DefiBridgeProcessed (
                    0,
                    convertArgs.interactionNonce,
                    convertArgs.totalInputValue,
                    outputValueA,
                    outputValueB,
                    true
                );
            }
            results.outputValueA = outputValueA;
            results.outputValueB = outputValueB;
            results.isAsync = isAsync;
        }
        require(success, 'Interaction Failed');

        // else {


        //     emit DefiBridgeProcessed(
        //     0,
        //     interactionNonce,
        //     totalInputValue,
        //     totalInputValue,
        //     inputAssetB.NOT_USED || inputAssetB.,
        //     success
        // );
        // }
        // TODO: Should probaby emit an event for failed?
    }

function transferTokensAsync(
        address bridgeContract,
        AztecTypes.AztecAsset memory asset,
        uint256 outputValue,
        uint256 interactionNonce
    ) internal {
        if (asset.assetType == AztecTypes.AztecAssetType.ETH) {
            require(
                outputValue == ethPayments[interactionNonce],
                "Rollup Processor: INSUFFICEINT_ETH_PAYMENT"
            );
            ethPayments[interactionNonce] = 0;
        } else if (
            asset.assetType == AztecTypes.AztecAssetType.ERC20 &&
            outputValue > 0
        ) {
            address tokenAddress = asset.erc20Address;
            bool success;

            assembly {
                // call token.transferFrom(bridgeAddressId, this, outputValue)
                let mPtr := mload(0x40)
                mstore(mPtr, TRANSFER_FROM_SELECTOR)
                mstore(add(mPtr, 0x04), bridgeContract)
                mstore(add(mPtr, 0x24), address())
                mstore(add(mPtr, 0x44), outputValue)
                success := call(gas(), tokenAddress, 0, mPtr, 0x64, 0x00, 0x20)
                if iszero(success) {
                    returndatacopy(0, 0, returndatasize())
                    revert(0x00, returndatasize())
                }
            }
        }

        // VIRTUAL Assets are not transfered.
    }

function unwrapETH(uint256 inputValue, AztecTypes.AztecAsset calldata outputAsset, uint256 interactionNonce) private returns (uint256 outputValue) {
        require(outputAsset.assetType == AztecTypes.AztecAssetType.ETH, "LidoBridge: Invalid Output Token");

        // Convert wstETH to stETH so we can exchange it on curve
        uint256 stETH = wrappedStETH.unwrap(inputValue);

        // Exchange stETH to ETH via curve
        IERC20(address(lido)).safeIncreaseAllowance(address(curvePool), stETH);
        outputValue = curvePool.exchange(curveStETHIndex, curveETHIndex, stETH, 0);

        // Send ETH to rollup processor
        IRollupProcessor(rollupProcessor).receiveEthFromBridge{value: outputValue}(interactionNonce);
    }

function tokenToLp(address _token, uint amount, address _lp, bool needDeposit) external {
        address receiver = msg.sender;
        if (needDeposit) {
          receiver = address(this);
        }
        IERC20Upgradeable(_token).safeTransferFrom(msg.sender, address(this), amount);
        _approveTokenIfNeeded(_token, address(router), amount);

        IPair pair = IPair(_lp);
        address token0 = pair.token0();
        address token1 = pair.token1();
        require(factory.getPair(token0, token1) == _lp, "NO_PAIR");

        uint liquidity;

        if (_token == token0 || _token == token1) {
            // swap half amount for other
            address other = _token == token0 ? token1 : token0;
            _approveTokenIfNeeded(other, address(router), amount);
            uint sellAmount = amount / 2;

            uint otherAmount = _swap(_token, sellAmount, other, address(this));
            pair.skim(address(this));

            (, , liquidity) = router.addLiquidity(_token, other, amount - sellAmount, otherAmount, 0, 0, receiver, block.timestamp);
        } else {
            uint bnbAmount = _token == wbnb ? _safeSwapToBNB(amount) : _swapTokenForBNB(_token, amount, address(this));
            liquidity = _swapBNBToLp(_lp, bnbAmount, receiver);
        }

        emit ZapToLP(_token, amount, _lp, liquidity);
        if (needDeposit) {
          deposit(_lp, liquidity, msg.sender);
        }

    }

function tokenToToken(address _token, uint _amount, address _to, bool needDeposit) external returns (uint amountOut){
      IERC20Upgradeable(_token).safeTransferFrom(msg.sender, address(this), _amount);
      _approveTokenIfNeeded(_token, address(router), _amount);

      if (needDeposit) {
        amountOut = _swap(_token, _amount, _to, address(this));
        deposit(_to, amountOut, msg.sender);
      } else {
        amountOut = _swap(_token, _amount, _to, msg.sender);
      }
    }

function zapOut(address _from, uint _amount) external {
        IERC20Upgradeable(_from).safeTransferFrom(msg.sender, address(this), _amount);
        _approveTokenIfNeeded(_from, address(router), _amount);

        IPair pair = IPair(_from);
        address token0 = pair.token0();
        address token1 = pair.token1();

        if (pair.balanceOf(_from) > 0) {
            pair.burn(address(this));
        }

        if (token0 == wbnb || token1 == wbnb) {
            router.removeLiquidityETH(token0 != wbnb ? token0 : token1, _amount, 0, 0, msg.sender, block.timestamp);
        } else {
            router.removeLiquidity(token0, token1, _amount, 0, 0, msg.sender, block.timestamp);
        }
    }

function deposit(address token, uint amount, address toUser) private {
