function getRoyaltiesReceiver(uint256 _editionId) external override view returns (address _receiver) {
        EditionAgreement storage agreement = editionAgreements[_editionId];
        if (agreement.fundsRecipient != address(0)) {
            return agreement.fundsRecipient;
        }
        return koda.getCreatorOfEdition(_editionId);
    }

function royaltyInfo(
        uint256 _tokenId,
        uint256 _value
    ) external override view returns (
        address _receiver,
        uint256 _royaltyAmount
    ) {
        uint256 _editionId = _editionFromTokenId(_tokenId);

        EditionAgreement storage agreement = editionAgreements[_editionId];

        // If quorum has been reached use the deployed royalties DAO
        if (agreement.fundsRecipient != address(0)) {
            return (agreement.fundsRecipient, agreement.expectedRoyalty);
        }

        // default return creator and royalty
        return (koda.getCreatorOfEdition(_editionId), agreement.expectedRoyalty);
    }

function setupAgreement(uint256 _editionId, uint256 _expectedRoyalty, bytes32 _agreementHash) public {
        require(accessControls.hasContractRole(_msgSender()), "Caller must to have contract role");
        require(editionAgreements[_editionId].agreementHash.length == 0, "Agreement already defined");

        // setup the schedule (N.B: due to one time check this could mean that the agreement can be defined post edition creation)
        editionAgreements[_editionId] = EditionAgreement(_expectedRoyalty, _agreementHash, address(0));
    }

function confirmAgreement(
        uint256 _editionId,
        address[] calldata participants, // proposed participants & splits
        uint256[] calldata splits, // TODO do we need splits and recipients ... ?
    // signatures
    // TODO is there a signature type/struct which would help, maybe in OZ even?
        uint8[] calldata sigV, bytes32[] calldata sigR, bytes32[] calldata sigS
    ) public {
        // can only be confirmed once and once only
        require(editionAgreements[_editionId].fundsRecipient == address(0), "Agreement already defined");

        // TODO validation
        // get existing agreement
        EditionAgreement storage agreement = editionAgreements[_editionId];

        // Compute expected hash
        bytes32 inputHash = _computeHash(_editionId, participants, splits);

        // confirm the agreements match
        require(inputHash == agreement.agreementHash, "Invalid agreement hash");

        // Ensure all participants signatures include (tokenId, array or recipients and splits, plus default royalty)
        bytes32 expectedSignedAgreement = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, inputHash));

        _validateAgreementSigs(_msgSender(), expectedSignedAgreement, participants, sigV, sigR, sigS);

        // Create a micro funds recipient - this will be where all money is now directed on every sale
        address splitter = Clones.clone(baseFundsSplitter);

        // IFundsHandler instance for handling all funds - this should not revert on receiving funds
        FundsReceiver(payable(splitter)).init(participants, splits);

        // assign newly created splitter
        agreement.fundsRecipient = address(splitter);

        emit EditionAgreementConfirmed(_editionId, splitter);
    }

function _editionFromTokenId(uint256 _tokenId) internal pure returns (uint256) {
        return (_tokenId / MAX_EDITION_SIZE) * MAX_EDITION_SIZE;
    }

function _computeHash(uint256 _editionId, address[] calldata _participants, uint256[] calldata _splits) internal pure returns (bytes32) {
        // EIP712 scheme: https://github.com/ethereum/EIPs/blob/master/EIPS/eip-712.md
        // create hash of expected signature params
        return keccak256(
            abi.encode(
                TX_TYPE_HASH, // scheme
                _editionId, // target token ID
                _participants, // the recipients
                _splits // the splits
            )
        );
    }

function confirm(uint256 _tokenId, uint8[] calldata sigV, bytes32[] calldata sigR, bytes32[] calldata sigS)
    override
    public {

        MultiHolder memory holder = multiHolderRoyalties[_tokenId];

        // EIP712 scheme: https://github.com/ethereum/EIPs/blob/master/EIPS/eip-712.md
        // create hash of expected signature params
        bytes32 inputHash = keccak256(
            abi.encode(
                TXTYPE_HASH, // scheme
                _tokenId, // target token ID
                holder.royaltyAmount, // total royalty percentage expected
                holder.recipients, // the recipients
                holder.splits // the splits
            )
        );

        // Ensure all participants signatures include (tokenId, array or recipients and splits, plus default royalty)
        bytes32 expectedSignedAgreement = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, inputHash));

        address[] memory totalRecipients = holder.recipients;

        // for each participant, check they have signed the agreement
        for (uint i = 0; i < totalRecipients.length; i++) {
            address recovered = ecrecover(expectedSignedAgreement, sigV[i], sigR[i], sigS[i]);
            require(recovered == totalRecipients[i], "Agreement not reached");
        }

        // Once all approved, confirm royalties set
        royaltiesSet[_tokenId] = true;

        // Setup a new funds splitter and assign a new funds split now all parties have assigned
        address splitter = Clones.clone(baseFundsSplitter);

        // Use either pull (FundsReceiver) or push (FundsSplitter) pattern
        // IFundsHandler splitterContract = FundSplitter(payable(splitter));
        IFundsHandler splitterContract = FundsReceiver(payable(splitter));
        splitterContract.init(totalRecipients, holder.splits);

        // assign newly created splitter
        holder.splitter = address(splitter);

        // clean up mappings to claw back some GAS
        delete multiHolderRoyalties[_tokenId].recipients;
        delete multiHolderRoyalties[_tokenId].splits;
    }

function reject(uint256 _tokenId, uint256 _quitterIndex)
    override
    public {

        // TODO make this less shit and GAS efficient ...

        // check quitter is at in the list
        require(multiHolderRoyalties[_tokenId].recipients[_quitterIndex] == _msgSender(), "Not a member");

        // assign last in array, overwriting the quitter
        multiHolderRoyalties[_tokenId].recipients[_quitterIndex] = multiHolderRoyalties[_tokenId].recipients[multiHolderRoyalties[_tokenId].recipients.length - 1];

        // shorten the array by one
        multiHolderRoyalties[_tokenId].recipients.pop();
    }

function permit(address owner, address spender, uint256 tokenId, uint deadline, uint8 v, bytes32 r, bytes32 s)
    override
    external {
        require(deadline != 0 && deadline >= block.timestamp, "Deadline expired");
        require(IERC721Ownable(address(this)).ownerOf(tokenId) == owner, "Invalid owner");

        // Create digest to check signatures
        bytes32 digest = keccak256(
            abi.encodePacked(
                "\x19\x01",
                _domainSeparator(),
                keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, tokenId, nonces[owner]++, deadline))
            )
        );

        // Has the original signer signed it
        address recoveredAddress = ecrecover(digest, v, r, s);
        require(recoveredAddress != address(0) && recoveredAddress == owner, "INVALID_SIGNATURE");

        // set approval for signature if passed
        _approval(owner, spender, tokenId);
    }

function setupRoyalty(uint256 _editionId, string memory _handlerName, address[] calldata _recipients, uint256[] calldata _splits)
    public
    payable
    returns (address proxy){

        // Get the specified funds handler
        address handler = handlers[_handlerName];

        // Clone funds handler as Minimal Proxy
        proxy = Clones.clone(handler);

        // Initialize proxy
        IFundsHandler(proxy).init(_recipients, _splits);

        // Verify that it was initialized properly
        require(IFundsHandler(proxy).totalRecipients() == _recipients.length);

        // Store address of proxy by edition id
        proxies[_editionId] = proxy;

        // Emit event
        emit ProxyDeployed(_editionId, _handlerName, proxy, _recipients, _splits);
    }

function setupRoyalty(uint256 _editionId, string memory _beaconName, address[] calldata _recipients, uint256[] calldata _splits)
    public
    payable
    returns (address proxy){

        // Get the specified beacon
        address beacon = beacons[_beaconName];

        // Create the initializer data
        bytes memory initData =
        abi.encodeWithSignature(
            "init(address[],uint256[])",
            _recipients,
            _splits
        );

        // Instantiate beacon proxy
        proxy = address(new BeaconProxy(beacon, initData));

        // Verify that it was initialized properly
        require(IFundsHandler(proxy).totalRecipients() == _recipients.length);

        // Store address of proxy by edition id
        proxies[_editionId] = proxy;

        // Emit event
        emit ProxyDeployed(_editionId, _beaconName, proxy, _recipients, _splits);
    }

