function drain() public nonReentrant override {

        // Check that there are funds to drain
        uint256 balance = address(this).balance;
        require(balance > 0, "No funds to drain");

        uint256 outstandingEthOwedToCollaborators = totalEthReceived - totalEthPaid;
        if (balance > outstandingEthOwedToCollaborators) {
            // when outstandingEthOwedToCollaborators is > 0 it means that ETH is owed to some collaborators (those who have not drawn down).
            // If balance is greater than outstandingEthOwedToCollaborators then the balance has grown since a collaborator has drawn down so increase total ETH received.
            // Otherwise, if ETH owed is zero, then we have simply received a new balance
            totalEthReceived += balance - outstandingEthOwedToCollaborators;
        }
        // note with the above we do not have to increase total received in the case balance is equal to what we owe collaborators

        uint256[] memory shares = new uint256[](recipients.length);

        // Calculate and send share for each recipient
        uint256 singleUnitOfValue = totalEthReceived / modulo;
        uint256 sumPaidOut;
        for (uint256 i = 0; i < recipients.length; i++) {
            address recipient = recipients[i];
            shares[i] = singleUnitOfValue * splits[i];

            // Deal with the first recipient later (see comment below)
            if (i != 0) {
                uint256 amountOwedToCollaborator = shares[i] - ethPaidToCollaborator[recipient];
                if (amountOwedToCollaborator > 0) {
                    ethPaidToCollaborator[recipient] += amountOwedToCollaborator;
                    payable(recipient).call{value : amountOwedToCollaborator}("");

                    sumPaidOut += amountOwedToCollaborator;
                }
            }
        }

        // The first recipient is a special address as it receives any dust left over from splitting up the funds
        address firstRecipient = recipients[0];
        uint256 amountOwedToCollaborator = shares[0] - ethPaidToCollaborator[firstRecipient];
        sumPaidOut += amountOwedToCollaborator;

        // now check for dust i.e. remainingBalance
        uint256 remainingBalance = totalEthReceived - sumPaidOut;
        // Either going to be a zero or non-zero value
        sumPaidOut += remainingBalance;
        // dust increases pay out for all recipients

        // increase amount owed to collaborator
        amountOwedToCollaborator += remainingBalance;

        if (amountOwedToCollaborator > 0) {
            ethPaidToCollaborator[firstRecipient] += amountOwedToCollaborator;
            payable(firstRecipient).call{value : amountOwedToCollaborator}("");
        }

        totalEthPaid += sumPaidOut;

        emit FundsDrained(balance, recipients, shares, address(0));
    }

function drainERC20(IERC20 token) public nonReentrant override {

        // Check that there are funds to drain
        uint256 balance = token.balanceOf(address(this));
        require(balance > 0, "No funds to drain");

        uint256[] memory shares = new uint256[](recipients.length);

        // Calculate and send share for each recipient
        uint256 singleUnitOfValue = balance / modulo;
        uint256 sumPaidOut;
        for (uint256 i = 0; i < recipients.length; i++) {
            shares[i] = singleUnitOfValue * splits[i];

            // Deal with the first recipient later (see comment below)
            if (i != 0) {
                token.transfer(recipients[i], shares[i]);
            }

            sumPaidOut += shares[i];
        }

        // The first recipient is a special address as it receives any dust left over from splitting up the funds
        uint256 remainingBalance = balance - sumPaidOut;
        // Either going to be a zero or non-zero value
        token.transfer(recipients[0], remainingBalance + shares[0]);

        emit FundsDrained(balance, recipients, shares, address(token));
    }

function drainShare() public override nonReentrant {
        // Check that there are funds to drain
        uint256 balance = address(this).balance;
        require(balance > 0, "No funds to drain");

        uint256 outstandingEthOwedToCollaborators = totalEthReceived - totalEthPaid;
        if (balance > outstandingEthOwedToCollaborators) {
            // when outstandingEthOwedToCollaborators is > 0 it means that ETH is owed to some collaborators (those who have not drawn down).
            // If balance is greater than outstandingEthOwedToCollaborators then the balance has grown since a collaborator has drawn down so increase total ETH received.
            // Otherwise, if ETH owed is zero, then we have simply received a new balance
            totalEthReceived += balance - outstandingEthOwedToCollaborators;
        }
        // note with the above we do not have to increase total received in the case balance is equal to what we owe collaborators

        address recipient;
        uint256 recipientIndex;
        for (uint i = 0; i < recipients.length; i++) {
            address _recipient = recipients[i];
            if (_recipient == msg.sender) {
                recipient = msg.sender;
                recipientIndex = i;
                break;
            }
        }
        require(recipient != address(0), "Nice try but you are not a collaborator");

        uint256 singleUnitOfValue = totalEthReceived / modulo;
        uint256 share = singleUnitOfValue * splits[recipientIndex];
        uint256 amountOwed = share - ethPaidToCollaborator[recipient];
        if (amountOwed > 0) {
            ethPaidToCollaborator[recipient] = amountOwed;
            totalEthPaid += amountOwed;
            payable(recipient).call{value : amountOwed}("");

            uint256[] memory shares = new uint256[](1);
            shares[0] = share;

            address[] memory recipients = new address[](1);
            recipients[0] = recipient;

            emit FundsDrained(amountOwed, recipients, shares, address(0));
        }
    }

function _buildOftTransfer(
        Quote calldata quote
    ) internal view returns (SendParam memory, MessagingFee memory, address) {
        bytes memory composeMsg = ComposeMsgCodec._encode(
            quote.signedParams.nonce,
            quote.signedParams.deadline,
            quote.signedParams.maxBpsToSponsor,
            quote.unsignedParams.maxUserSlippageBps,
            quote.signedParams.finalRecipient,
            quote.signedParams.finalToken,
            quote.signedParams.executionMode,
            quote.signedParams.actionData
        );

        bytes memory extraOptions = MinimalLZOptions
            .newOptions()
            .addExecutorLzReceiveOption(uint128(quote.signedParams.lzReceiveGasLimit), uint128(0))
            .addExecutorLzComposeOption(uint16(0), uint128(quote.signedParams.lzComposeGasLimit), uint128(0));

        SendParam memory sendParam = SendParam(
            quote.signedParams.dstEid,
            quote.signedParams.destinationHandler,
            // Only support OFT sends that don't take fees in sent token. Set `minAmountLD = amountLD` to enforce this
            quote.signedParams.amountLD,
            quote.signedParams.amountLD,
            extraOptions,
            composeMsg,
            // Only support empty OFT commands
            EMPTY_OFT_COMMAND
        );

        MessagingFee memory fee = IOFT(OFT_MESSENGER).quoteSend(sendParam, false);

        return (sendParam, fee, quote.unsignedParams.refundRecipient);
    }

function transferERC20CoreToCore(uint64 erc20CoreIndex, address to, uint64 amountCore) internal {
        bytes memory action = abi.encode(to, erc20CoreIndex, amountCore);
        bytes memory payload = abi.encodePacked(SPOT_SEND_HEADER, action);

        ICoreWriter(CORE_WRITER_PRECOMPILE_ADDRESS).sendRawAction(payload);
    }

function submitLimitOrder(
        uint32 asset,
        bool isBuy,
        uint64 limitPriceX1e8,
        uint64 sizeX1e8,
        bool reduceOnly,
        Tif tif,
        uint128 cloid
    ) internal {
        // Basic sanity checks
        if (limitPriceX1e8 == 0) revert LimitPxIsZero();
        if (sizeX1e8 == 0) revert OrderSizeIsZero();
        if (tif == Tif.None || uint8(tif) > uint8(type(Tif).max)) revert InvalidTif();

        // Encode the action
        bytes memory encodedAction = abi.encode(asset, isBuy, limitPriceX1e8, sizeX1e8, reduceOnly, uint8(tif), cloid);

        // Prefix with the limit-order header
        bytes memory data = abi.encodePacked(LIMIT_ORDER_HEADER, encodedAction);

        // Enqueue limit order to HyperCore via CoreWriter precompile
        ICoreWriter(CORE_WRITER_PRECOMPILE_ADDRESS).sendRawAction(data);
    }

function cancelOrderByCloid(uint32 asset, uint128 cloid) internal {
        // Encode the action
        bytes memory encodedAction = abi.encode(asset, cloid);

        // Prefix with the cancel-by-cloid header
        bytes memory data = abi.encodePacked(CANCEL_BY_CLOID_HEADER, encodedAction);

        // Enqueue cancel order by CLOID to HyperCore via CoreWriter precompile
        ICoreWriter(CORE_WRITER_PRECOMPILE_ADDRESS).sendRawAction(data);
    }

function spotBalance(address account, uint64 token) internal view returns (uint64 balance) {
        (bool success, bytes memory result) = SPOT_BALANCE_PRECOMPILE_ADDRESS.staticcall(abi.encode(account, token));
        if (!success) revert SpotBalancePrecompileCallFailed();
        SpotBalance memory _spotBalance = abi.decode(result, (SpotBalance));
        return _spotBalance.total;
    }

function coreUserExists(address user) internal view returns (bool) {
        (bool success, bytes memory result) = CORE_USER_EXISTS_PRECOMPILE_ADDRESS.staticcall(abi.encode(user));
        if (!success) revert CoreUserExistsPrecompileCallFailed();
        CoreUserExists memory _coreUserExists = abi.decode(result, (CoreUserExists));
        return _coreUserExists.exists;
    }

function spotPx(uint32 index) internal view returns (uint64) {
        (bool success, bytes memory result) = SPOT_PX_PRECOMPILE_ADDRESS.staticcall(abi.encode(index));
        if (!success) revert SpotPxPrecompileCallFailed();
        return abi.decode(result, (uint64));
    }

function tokenInfo(uint32 erc20CoreIndex) internal view returns (TokenInfo memory) {
